import{describe,it,expect,beforeEach,vi}from"vitest";import fs from"node:fs";import path from"node:path";const LOCALES=path.resolve(__dirname,"../../i18n/locales");async function mountSwitcher(){document.body.innerHTML='<header class="navbar"></header>',globalThis.fetch=vi.fn(async e=>{const t=String(e).match(/([a-z]{2})\.json$/)?.[1],o=path.join(LOCALES,`${t}.json`);return t&&fs.existsSync(o)?{ok:!0,json:async()=>JSON.parse(fs.readFileSync(o,"utf8"))}:{ok:!1,json:async()=>({})}}),vi.resetModules(),await(import("../../js-modules/language-switcher.js")),await new Promise(e=>setTimeout(e,0));const e=document.querySelector('[data-testid="language-switcher"]');return{wrapper:e,button:e.querySelector(".lang-switcher__button"),menu:e.querySelector(".lang-switcher__menu"),options:()=>Array.from(e.querySelectorAll('[role="option"]'))}}const key=(e,t)=>e.dispatchEvent(new window.KeyboardEvent("keydown",{key:t,bubbles:!0}));describe("language switcher keyboard access",()=>{beforeEach(()=>{localStorage.clear()}),it("mounts a switcher with one option per available language",async()=>{const{options:e}=await mountSwitcher();expect(e().length).toBeGreaterThan(1)}),it("makes every option focusable",async()=>{const{options:e}=await mountSwitcher();for(const t of e())expect(t.hasAttribute("tabindex")).toBe(!0),expect(t.tabIndex).toBe(-1)}),it("opens the menu and focuses the first option on ArrowDown",async()=>{const{button:e,menu:t,options:o}=await mountSwitcher();expect(t.hidden).toBe(!0),key(e,"ArrowDown"),expect(t.hidden).toBe(!1),expect(document.activeElement).toBe(o()[0])}),it("opens the menu and focuses the last option on ArrowUp",async()=>{const{button:e,options:t}=await mountSwitcher();key(e,"ArrowUp");const o=t();expect(document.activeElement).toBe(o[o.length-1])}),it("cycles focus through the options and wraps at the ends",async()=>{const{button:e,options:t}=await mountSwitcher();key(e,"ArrowDown");const o=t();key(o[0],"ArrowDown"),expect(document.activeElement).toBe(o[1]),key(o[1],"ArrowUp"),expect(document.activeElement).toBe(o[0]),key(o[0],"ArrowUp"),expect(document.activeElement).toBe(o[o.length-1])}),it("closes on Escape and returns focus to the button",async()=>{const{button:e,menu:t,options:o}=await mountSwitcher();key(e,"ArrowDown"),key(o()[0],"Escape"),expect(t.hidden).toBe(!0),expect(document.activeElement).toBe(e),expect(e.getAttribute("aria-expanded")).toBe("false")}),it("selects a language with Enter",async()=>{const{button:e,menu:t,options:o}=await mountSwitcher();key(e,"ArrowDown");const n=o().find(e=>"hi"===e.dataset.langCode);key(n,"Enter"),await new Promise(e=>setTimeout(e,0)),expect(localStorage.getItem("incredible-india-language")).toBe("hi"),expect(t.hidden).toBe(!0)}),it("selects a language with Space",async()=>{const{button:e,options:t}=await mountSwitcher();key(e,"ArrowDown");const o=t().find(e=>"ta"===e.dataset.langCode);key(o," "),await new Promise(e=>setTimeout(e,0)),expect(localStorage.getItem("incredible-india-language")).toBe("ta")})});